(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.3)*20+Math.cos(y*0.012-t*0.2)*15;
  const w1y = Math.cos(y*0.015-t*0.25)*20+Math.sin(x*0.013+t*0.35)*15;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.02-t*0.4)*10+Math.cos(my*0.018+t*0.3)*8;
  const w2y = Math.cos(my*0.02+t*0.35)*10+Math.sin(mx*0.016-t*0.45)*8;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.85],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*40,0.13,1.8,1.15]
