  }
  const n=src.length,act=aS/n,inh=iS/n,crs=cross/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin(sx*0.08+sy*0.06-t*1.5)*0.4+Math.sin(sx*0.12-sy*0.08+t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*5-t*1.2))*0.35+Math.sin(dist*0.07-ang*2+t*0.8)*0.3;
  const cs=40,cX=Math.floor(sx/cs),cY=Math.floor(sy/cs);
  let mD=999,mD2=999;
  for(let di=-1;di<=1;di++)for(let dj=-1;dj<=1;dj++){
