  const r1=Math.tanh(r0*1.5-cField*0.8),r2=Math.tanh(r1*1.2+r0*0.5-cField*0.3);
  const detail=Math.sin(sx*0.3+Math.sin(sy*0.2+t)*2)*Math.sin(sy*0.25+Math.cos(sx*0.15-t*1.3)*2)*0.15;
  const blend=r2*0.6+cField*0.2+detail*0.1+spiral*0.1,v=blend*0.5+0.5;
