  const pal=[[5,12,45],[12,40,85],[18,75,120],[25,130,135],[45,170,140],[120,195,130],[200,195,90],[230,160,80],[210,110,75],[180,70,80],[130,40,70],[70,25,55],[30,15,48],[5,12,45]];
